// The node:http WRITE side under the island: OutgoingMessage and
// ServerResponse.
//
// express builds its response object at MODULE LOAD as
// Object.create(http.ServerResponse.prototype) and composes its own
// methods on top; every request object then chains through it. Without
// those two constructors express/lib/response.js died on the first line,
// taking express, router, send, body-parser and serve-static with it.
// This package reproduces that shape — the prototype chain, the
// Object.create composition, a per-request object whose proto is the
// composed one — plus the header/status surface express drives through
// (setHeader/getHeader/getHeaders/hasHeader/removeHeader/appendHeader,
// writeHead, statusCode/statusMessage/headersSent, write/end).
//
// It also pins the EventEmitter MIXIN express performs on its `app`
// function (merge-descriptors copies EventEmitter.prototype onto a plain
// function that never ran the constructor): Node materializes _events
// lazily inside the methods, so the mixed-in emitter works.
//
// NOT compared: res.outputData. Node's first entry is the serialized wire
// header block (a socket's work, which the island never does) and its
// Date header is not reproducible across two runs; the island buffers
// body writes only. Everything readable through the public surface —
// status, headers, finished/headersSent — is compared.
import http from "node:http";
import { EventEmitter } from "node:events";

function mkReq(method, url) {
  const req = new http.IncomingMessage(null, 0, "", []);
  req.method = method;
  req.url = url;
  req.headers = { host: "localhost" };
  return req;
}

function tryIt(fn) {
  try {
    const v = fn();
    return "ok:" + String(v);
  } catch (err) {
    return "throw:" + err.code + ":" + err.message;
  }
}

export function report() {
  const lines = [];
  const push = (label, v) => lines.push(label + " " + v);

  // The constructors exist and are functions.
  push("kinds:", typeof http.OutgoingMessage + "/" + typeof http.ServerResponse);
  push("names:", http.OutgoingMessage.name + "/" + http.ServerResponse.name);

  // The chain express relies on: ServerResponse -> OutgoingMessage -> EventEmitter.
  push(
    "chain:",
    (http.ServerResponse.prototype instanceof http.OutgoingMessage) +
      "/" +
      (Object.getPrototypeOf(http.ServerResponse.prototype) === http.OutgoingMessage.prototype) +
      "/" +
      (http.OutgoingMessage.prototype instanceof EventEmitter),
  );

  // The methods express calls must live on the PROTOTYPES, not on instances
  // (Object.create only inherits prototype properties).
  const onProto = (proto, names) =>
    names.map((n) => (typeof proto[n] === "function" ? "1" : "0")).join("");
  push(
    "outgoing-proto:",
    onProto(http.OutgoingMessage.prototype, [
      "setHeader",
      "getHeader",
      "getHeaders",
      "getHeaderNames",
      "hasHeader",
      "removeHeader",
      "appendHeader",
      "write",
      "end",
      "flushHeaders",
      "addTrailers",
      "cork",
      "uncork",
      "setTimeout",
      "destroy",
      "on",
      "emit",
    ]),
  );
  push(
    "response-proto:",
    onProto(http.ServerResponse.prototype, [
      "writeHead",
      "writeContinue",
      "assignSocket",
      "detachSocket",
      "_implicitHeader",
      "setHeader",
      "end",
    ]),
  );

  // A plain instance: express's request-time defaults.
  const res0 = new http.ServerResponse(mkReq("GET", "/"));
  push(
    "instance:",
    res0.statusCode +
      "/" +
      String(res0.statusMessage) +
      "/" +
      res0.headersSent +
      "/" +
      res0.finished +
      "/" +
      res0.sendDate +
      "/" +
      (res0 instanceof http.OutgoingMessage) +
      "/" +
      (res0 instanceof EventEmitter) +
      "/" +
      res0.constructor.name,
  );

  // The header store.
  const res1 = new http.ServerResponse(mkReq("GET", "/"));
  res1.setHeader("Content-Type", "text/html");
  res1.setHeader("X-Powered-By", "Express");
  res1.appendHeader("Set-Cookie", "a=1");
  res1.appendHeader("Set-Cookie", "b=2");
  push("get:", res1.getHeader("content-type") + "/" + String(res1.getHeader("nope")));
  push("has:", res1.hasHeader("X-POWERED-BY") + "/" + res1.hasHeader("nope"));
  push("names:", JSON.stringify(res1.getHeaderNames()));
  push("raw-names:", JSON.stringify(res1.getRawHeaderNames()));
  push("headers:", JSON.stringify(res1.getHeaders()));
  push("headers-proto:", String(Object.getPrototypeOf(res1.getHeaders())));
  res1.removeHeader("x-powered-by");
  push("after-remove:", JSON.stringify(res1.getHeaderNames()));

  // Refusals express's own error paths depend on.
  push("bad-name:", tryIt(() => res1.setHeader("bad header", "x")));
  push("bad-value:", tryIt(() => res1.setHeader("X-Ok", undefined)));

  // writeHead: status line, implicit reason, header merge, headersSent.
  const res2 = new http.ServerResponse(mkReq("GET", "/"));
  res2.writeHead(404, { "X-A": "1" });
  push(
    "writehead:",
    res2.statusCode + "/" + res2.statusMessage + "/" + res2.headersSent + "/" + res2.getHeader("x-a"),
  );
  push("sent-set:", tryIt(() => res2.setHeader("X-B", "2")));
  push("sent-remove:", tryIt(() => res2.removeHeader("x-a")));

  // With the progressive api already open, writeHead's bag MERGES into the
  // readable store instead of going straight to the wire block.
  const res2b = new http.ServerResponse(mkReq("GET", "/"));
  res2b.setHeader("X-Pre", "p");
  res2b.writeHead(200, { "X-A": "1" });
  push("writehead-merge:", JSON.stringify(res2b.getHeaders()));

  const res3 = new http.ServerResponse(mkReq("GET", "/"));
  res3.writeHead(201, "Made It", { "X-C": "3" });
  push("writehead-reason:", res3.statusCode + "/" + res3.statusMessage);
  push("bad-status:", tryIt(() => new http.ServerResponse(mkReq("GET", "/")).writeHead(7)));

  // The base class refuses to render a first line — the subclass knows how.
  push("implicit:", tryIt(() => new http.OutgoingMessage().write("x")));

  // write/end drive the implicit header and the ended flags.
  const res4 = new http.ServerResponse(mkReq("GET", "/"));
  res4.statusCode = 202;
  push("pre-write:", res4.headersSent + "/" + res4.writableEnded);
  res4.write("part");
  push("post-write:", res4.headersSent + "/" + res4.statusCode + "/" + res4.statusMessage);
  res4.end("done");
  push("post-end:", res4.finished + "/" + res4.writableEnded + "/" + res4.writable);

  // THE express SHAPE: a module-load Object.create over the prototype,
  // methods composed on top, and a per-request object chaining to it.
  const proto = Object.create(http.ServerResponse.prototype);
  proto.status = function status(code) {
    this.statusCode = code;
    return this;
  };
  proto.send = function send(body) {
    this.setHeader("Content-Type", "text/html; charset=utf-8");
    this.setHeader("Content-Length", String(Buffer.byteLength(body)));
    sent.push(body);
    this.end(body);
    return this;
  };
  const sent = [];
  push(
    "proto-create:",
    (proto instanceof http.ServerResponse) +
      "/" +
      (typeof proto.setHeader === "function") +
      "/" +
      (typeof proto.send === "function"),
  );

  const res5 = new http.ServerResponse(mkReq("GET", "/"));
  Object.setPrototypeOf(res5, proto);
  res5.status(201).send("hello");
  push("composed:", res5.statusCode + "/" + res5.finished + "/" + res5.headersSent);
  push("composed-headers:", JSON.stringify(res5.getHeaders()));
  push("composed-body:", JSON.stringify(sent));

  // express's `app` is a FUNCTION with EventEmitter.prototype mixed in and
  // no constructor run: the emitter has to materialize its store lazily.
  const app = function app() {};
  for (const key of Object.getOwnPropertyNames(EventEmitter.prototype)) {
    if (key === "constructor") continue;
    Object.defineProperty(app, key, Object.getOwnPropertyDescriptor(EventEmitter.prototype, key));
  }
  const seen = [];
  app.on("mount", (parent) => seen.push("mount:" + parent));
  push("mixin:", app.emit("mount", "root") + "/" + app.listenerCount("mount") + "/" + seen.join(","));
  push("mixin-names:", JSON.stringify(app.eventNames()));

  return lines.join("\n");
}
